  ["CurrencyDescription:1792"] = { "L'onore si ottiene uccidendo i membri della fazione avversaria nel combattimento PvP. Puoi usare i punti onore per acquistare oggetti speciali.", 0xdcfb3ea8, "." },
  ["CurrencyDescription:3402"] = { "Vale una quantità considerevole d'oro ed è quindi usato come valuta provvisoria dalle organizzazioni mercantili più attive. I membri della Durotar Supply and Logistics o della Azeroth Commerce Authority sarebbero disposti a scambiarlo.", 0xab4f48ae, "." },
  ["CurrencyDescription:3468"] = { "I punti grado si ottengono completando gli incarichi affidati a Meccania o partecipando ai campi di battaglia. I punti grado aumentano il tuo grado PvP, che ti permette di acquistare oggetti speciali.", 0xa7e22a48, "." },
  ["CurrencyDescription:3469"] = { "Questa valuta sta lentamente uscendo dalla circolazione, ma gode ancora di un tasso di cambio molto favorevole nelle città dei goblin dei Regni Orientali e di Kalimdor.", 0x15a0429b, "." },
  ["CurrencyDescription:515"] = { "Si ottiene vincendo ai giochi o facendo favori alla Fiera di Lunacupa.", 0xa7f0a300, "." },
